import java.util.*;class Solution{List<String>o=new ArrayList<>();void f(char[]h,boolean[]u,StringBuilder c,Character mid){if(c.length()==h.length){String a=c.toString();String r=a+(mid==null?"":mid)+new StringBuilder(a).reverse();o.add(r);return;}for(int i=0;i<h.length;i++){if(u[i]||(i>0&&h[i]==h[i-1]&&!u[i-1]))continue;u[i]=true;c.append(h[i]);f(h,u,c,mid);c.deleteCharAt(c.length()-1);u[i]=false;}}public List<String> generatePalindromes(String s){int[]c=new int[256];for(char x:s.toCharArray())c[x]++;int odd=0;Character mid=null;StringBuilder h=new StringBuilder();for(int i=0;i<256;i++){if((c[i]&1)==1){odd++;mid=(char)i;}for(int j=0;j<c[i]/2;j++)h.append((char)i);}if(odd>1)return o;f(h.toString().toCharArray(),new boolean[h.length()],new StringBuilder(),mid);return o;}}
